import {W,H,newGame,fire,bestShot,trace,weapons} from './rules.js';
import * as online from './online.js';
const $=s=>document.querySelector(s),canvas=$('#field'),ctx=canvas.getContext('2d');
let game=null,kind=null,room=null,animation=null,poll=null,busy=false,lastVersion=-1;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function status(s){$('#status').textContent=s;}function onlineStatus(s){$('#online-status').textContent=s;}
function controls(){const can=!!game&&game.winner===null&&!busy&&(kind!=='online'||(room?.ready&&room.seat===game.turn))&&(kind!=='solo'||game.turn===0);$('#fire').disabled=!can;$('#angle-value').textContent=$('#angle').value+'°';$('#power-value').textContent=$('#power').value+'%';$('#player0').innerHTML=game?`<b>${esc(game.players[0].name)}</b><small>♥ ${game.players[0].hp} · ★ ${game.players[0].score} · ◇ ${game.players[0].cash}</small>`:'';$('#player1').innerHTML=game?`<b>${esc(game.players[1].name)}</b><small>♥ ${game.players[1].hp} · ★ ${game.players[1].score} · ◇ ${game.players[1].cash}</small>`:'';$('#round').textContent=game?`RUNDE ${game.round} / ${game.maxRounds}  ·  VIND ${game.wind>0?'→':game.wind<0?'←':'·'} ${Math.abs(game.wind)}`:'';$('#connection').textContent=kind==='online'?'● ONLINE':'● LOKAL';}
function sky(){const grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'#10273d');grad.addColorStop(.7,'#284c64');grad.addColorStop(1,'#6c7772');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);ctx.fillStyle='#8bb3bc';for(let i=0;i<48;i++){const x=(i*137+31)%W,y=(i*83+19)%220;ctx.globalAlpha=.25+(i%3)*.13;ctx.fillRect(x,y,2,2);}ctx.globalAlpha=1;ctx.fillStyle='#e7a678';ctx.beginPath();ctx.arc(765,105,32,0,7);ctx.fill();}
function draw(){sky();if(!game){ctx.fillStyle='#d9edf0';ctx.font='bold 42px system-ui';ctx.textAlign='center';ctx.fillText('Klar til kamp?',W/2,235);ctx.font='20px system-ui';ctx.fillText('Vælg modstander for at begynde',W/2,275);return;}const g=game.ground;ctx.beginPath();ctx.moveTo(0,H);ctx.lineTo(0,g[0]);for(let x=1;x<W;x+=2)ctx.lineTo(x,g[x]);ctx.lineTo(W,H);ctx.closePath();const grad=ctx.createLinearGradient(0,345,0,H);grad.addColorStop(0,'#5f8065');grad.addColorStop(.15,'#436656');grad.addColorStop(1,'#253d3d');ctx.fillStyle=grad;ctx.fill();ctx.strokeStyle='#9bbd86';ctx.lineWidth=3;ctx.beginPath();for(let x=0;x<W;x+=3){if(x===0)ctx.moveTo(x,g[x]);else ctx.lineTo(x,g[x]);}ctx.stroke();for(let i=0;i<2;i++){const p=game.players[i],x=p.x,y=g[x]-11;ctx.fillStyle=i?'#ec8f79':'#79d5d0';ctx.fillRect(x-18,y-4,36,15);ctx.fillRect(x-12,y-12,24,10);ctx.fillStyle='#203542';ctx.fillRect(x-14,y+9,28,5);const dir=i?-1:1,a=p.angle*Math.PI/180;ctx.strokeStyle=i?'#ffd0a7':'#c3ffff';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(x,y-11);ctx.lineTo(x+dir*25*Math.cos(a),y-11-25*Math.sin(a));ctx.stroke();ctx.fillStyle='#172a35';ctx.fillRect(x-22,y-35,44,7);ctx.fillStyle=p.hp>30?'#90e1a6':'#ff8c83';ctx.fillRect(x-22,y-35,44*p.hp/100,7);}if(animation){const {path,index,hit}=animation;ctx.strokeStyle='#ffe0a0';ctx.lineWidth=3;ctx.beginPath();for(let j=0;j<Math.min(index,path.length);j++){const [x,y]=path[j];j?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();if(index<path.length){const [x,y]=path[index];ctx.fillStyle='#fff0ae';ctx.beginPath();ctx.arc(x,y,6,0,7);ctx.fill();}else{ctx.fillStyle='#ffb17399';ctx.beginPath();ctx.arc(hit.x,hit.y,Math.min(42,(index-path.length)*4),0,7);ctx.fill();}}else if(kind!=='online'||room?.seat===game.turn){const angle=Number($('#angle').value),power=Number($('#power').value);const t=trace(game,game.turn,angle,power);ctx.strokeStyle='#b4e7dd77';ctx.setLineDash([3,8]);ctx.lineWidth=2;ctx.beginPath();t.path.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();ctx.setLineDash([]);}}
function animate(result,done){animation={path:result.hit.path,index:0,hit:result.hit};function frame(){animation.index+=Math.max(1,Math.ceil(animation.path.length/35));draw();if(animation.index<animation.path.length+12)requestAnimationFrame(frame);else{animation=null;draw();done?.();}}requestAnimationFrame(frame);}
function describe(result){const hit=result.damages[1-result.actor],self=result.damages[result.actor];if(game.winner!==null)return `${game.players[game.winner].name} vinder kampen! Slutscore ${game.players[0].score}–${game.players[1].score}.`;if(result.ended)return `Runde ${game.round-1} slut. ${hit?hit+' skade på modstanderen.':''} Ny slagmark!`;return hit?`${game.players[result.actor].name} ramte for ${hit} skade${self?' og tog '+self+' selv':''}.`:`${game.players[result.actor].name} skød. ${self?'Egen skade: '+self+'.':'Ingen træffer.'}`;}
function after(result){status(describe(result));controls();draw();if(kind==='solo'&&game.turn===1&&game.winner===null){busy=true;controls();setTimeout(()=>{const shot=bestShot(game,1);const r=fire(game,shot);animate(r,()=>{busy=false;after(r);});},650);}}
function reset(mode){clearInterval(poll);poll=null;room=null;kind=mode;game=newGame({mode:$('#mode').value,names:mode==='solo'?[$('#name').value.trim()||'Du','Computer']:[$('#name').value.trim()||'Spiller 1','Spiller 2']});lastVersion=-1;busy=false;status(mode==='solo'?'Din tur. Vælg vinkel og kraft.':'Spiller 1 begynder.');controls();draw();}
$('#solo').onclick=()=>reset('solo');$('#local').onclick=()=>reset('local');for(const id of ['angle','power'])$('#'+id).oninput=()=>{controls();draw();};$('#weapon').onchange=controls;
$('#fire').onclick=async()=>{if($('#fire').disabled)return;const shot={angle:Number($('#angle').value),power:Number($('#power').value),weapon:$('#weapon').value};busy=true;controls();try{if(kind==='online'){const next=await online.rpc('aa_fire',{p_code:room.code,p_version:room.version,p_angle:shot.angle,p_power:shot.power,p_weapon:shot.weapon});await sync(next);}else{const result=fire(game,shot);animate(result,()=>{busy=false;after(result);});}}catch(e){status(e.message);busy=false;controls();}};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();$('#fire').click();}});
async function identify(){const p=await online.profile();if(p?.nickname){$('#name').value=p.nickname;onlineStatus(`Logget ind som ${p.nickname}.`);}else onlineStatus('Skriv et ledigt navn og gem profilen.');return p;}
$('#save-name').onclick=async()=>{try{const name=$('#name').value.trim();if(!/^[\p{L}\p{N} _-]{2,20}$/u.test(name))throw Error('Brug 2–20 bogstaver eller tal.');await online.claim(name);await identify();}catch(e){onlineStatus(e.message);}};
$('#player-code').onclick=async()=>{try{const c=await online.createCode();$('#code-result').textContent=`${c.nickname}: ${c.code} — gem koden privat.`;}catch(e){$('#code-result').textContent=e.message;}};
$('#link').onclick=async()=>{try{const r=await online.useCode($('#name').value.trim(),$('#link-code').value.trim());if(r.error)throw Error(r.error);$('#link-code').value='';await identify();$('#code-result').textContent='Profilen er tilknyttet.';}catch(e){$('#code-result').textContent=e.message;}};
async function sync(next){if(!next)return;room=next;$('#room').textContent=`Kampkode: ${next.code} · ${next.ready?'Kampen er klar':'Venter på modstander…'}`;$('#code').value=next.code;let fresh=false;if(!game||kind!=='online'||game.seed!==next.seed){game=newGame({seed:next.seed,mode:next.mode,names:[next.host_name||'Vært',next.guest_name||'Gæst']});kind='online';lastVersion=0;fresh=true;}game.players[0].name=next.host_name||'Vært';game.players[1].name=next.guest_name||'Gæst';if(next.version<lastVersion){game=newGame({seed:next.seed,mode:next.mode,names:[next.host_name,next.guest_name]});lastVersion=0;}const pending=next.shots.slice(lastVersion);for(const shot of pending){if(game.winner!==null)break;const r=fire(game,shot);status(describe(r));}lastVersion=next.version;busy=false;controls();draw();if(fresh)status(next.ready?(next.seat===0?'Din tur.':'Venter på værtens skud.'):'Del kampkoden med en anden spiller.');else if(pending.length&&game.winner===null)status(game.turn===next.seat?'Din tur!':'Modstanderens tur.');}
function startPolling(){clearInterval(poll);poll=setInterval(async()=>{if(!room||document.hidden)return;try{const next=await online.rpc('aa_state',{p_code:room.code});if(next.version!==room.version||next.ready!==room.ready)await sync(next);else{room=next;controls();}}catch(e){onlineStatus('Forbindelsen blev afbrudt: '+e.message);}},3000);}
$('#host').onclick=async()=>{try{await identify();const next=await online.rpc('aa_host',{p_mode:$('#mode').value});await sync(next);startPolling();onlineStatus('Kamp oprettet. Del koden med modstanderen.');}catch(e){onlineStatus(e.message);}};
$('#join').onclick=async()=>{try{await identify();const next=await online.rpc('aa_join',{p_code:$('#code').value.trim()});await sync(next);startPolling();onlineStatus('Du er med i kampen.');}catch(e){onlineStatus(e.message);}};
draw();controls();
